var i=`disaster-recovery-rpo-and-rto`;var s=100;var o={en:[{id:`T100-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Scalability is the ability to handle more load by adding resources or optimizing design.`},{id:`B`,text:`Recovery Point Objective (RPO) is the maximum acceptable data-loss window; Recovery Time Objective (RTO) is the target time to restore service after a disruption.`},{id:`C`,text:`Immutable infrastructure replaces running instances with newly built images rather than patching them in place.`},{id:`D`,text:`Load balancing distributes requests or work across instances to improve utilization, capacity and availability.`}]},{id:`T100-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Define which failures to tolerate: instance crash, zone loss, timeout, bad data or dependency unavailability.`},{id:`B`,text:`Choose user-centric indicators such as successful booking confirmation rate or latency percentiles.`},{id:`C`,text:`Instrument critical workflows with correlation IDs, structured logs, duration histograms, error rates and distributed spans.`},{id:`D`,text:`Map critical services and datasets to objectives, then design backups, replicas, restore automation, runbooks and drills.`}]},{id:`T100-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A hotel booking system may require near-zero loss for confirmed payments while tolerating several hours of lost analytics events.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Feature flags may separately control exposure of new business behavior.`},{id:`B`,text:`Different datasets therefore need different protection tiers.`},{id:`C`,text:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`},{id:`D`,text:`Long WebSocket sessions may need different connection handling than short HTTP requests.`}]},{id:`T100-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Redundant replicas sharing one database or cloud zone may share the same failure mode.`},{id:`B`,text:`An SLA target should not be copied blindly into internal SLOs.`},{id:`C`,text:`Autoscaling cannot compensate for serial bottlenecks or unbounded contention.`},{id:`D`,text:`A replica is not a tested backup; deletion and ransomware can propagate.`}]},{id:`T100-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Recovery Point Objective (RPO) is the maximum acceptable data-loss window; Recovery Time Objective (RTO) is the target time to restore service after a disruption.`}]}]},{id:`T100-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`RPO specifies how quickly a system must recover, while RTO specifies permissible data loss.`}]}]},{id:`T100-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Very low RPO/RTO is expensive and must be justified against revenue and compliance impact.`}]}]},{id:`T100-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Recovery Point Objective (RPO) is the maximum acceptable data-loss window; Recovery Time Objective (RTO) is the target time to restore service after a disruption.`},{id:`B`,text:`Untested backups are enough to guarantee recovery within the RTO.`},{id:`C`,text:`Scalability and elasticity mean exactly the same capacity behavior.`},{id:`D`,text:`Map critical services and datasets to objectives, then design backups, replicas, restore automation, runbooks and drills.`}]},{id:`T100-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Different datasets therefore need different protection tiers.`},{id:`B`,text:`Very low RPO/RTO is expensive and must be justified against revenue and compliance impact.`},{id:`C`,text:`RPO specifies how quickly a system must recover, while RTO specifies permissible data loss.`},{id:`D`,text:`A fallback that silently returns incorrect prices is always preferable to failure.`}]},{id:`T100-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A hotel booking system may require near-zero loss for confirmed payments while tolerating several hours of lost analytics events.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to model failures of mail, cache and database dependencies separately and define degraded behavior, recovery tests and observability.`},{id:`B`,text:`Ask an agent to load-model a booking API, identify bottlenecks, recommend a scaling policy and specify database saturation safeguards.`},{id:`C`,text:`Ask an agent to define booking-confirmation SLIs, a measurable SLO, alert thresholds and an error-budget policy. Verify the measurement excludes only justified cases.`},{id:`D`,text:`Ask an agent for a disaster recovery plan for reservations, payments and analytics with separate RPO/RTO, restore order, backup tests and communication procedures.`}]},{id:`T100-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How will you verify that backups are restorable before the real disaster?`}]}]},{id:`T100-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A hotel booking system may require near-zero loss for confirmed payments while tolerating several hours of lost analytics events.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T100-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A hotel booking system may require near-zero loss for confirmed payments while tolerating several hours of lost analytics events.`,b:!0},{t:` — propose three checks for `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T100-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A hotel booking system may require near-zero loss for confirmed payments while tolerating several hours of lost analytics events.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T100-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Disaster Recovery: RPO & RTO`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A hotel booking system may require near-zero loss for confirmed payments while tolerating several hours of lost analytics events.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T100-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Масштабованість — здатність обслуговувати більше навантаження за рахунок ресурсів або оптимізацій.`},{id:`B`,text:`RPO — максимально допустимий проміжок втрати даних; RTO — цільовий час повернення сервісу після аварії.`},{id:`C`,text:`Незмінна інфраструктура замінює запущені інстанси новими зібраними образами замість ручного патчингу.`},{id:`D`,text:`Балансування розподіляє запити між інстансами задля кращого використання ресурсів, пропускної здатності та доступності.`}]},{id:`T100-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Визначте допустимі відмови: падіння інстансу, зони, timeout, некоректні дані чи недоступність залежності.`},{id:`B`,text:`Обирайте орієнтовані на користувача показники: успішність підтверджень або перцентилі затримки.`},{id:`C`,text:`Інструментуйте важливі сценарії correlation ID, структурованими логами, гістограмами затримок, часткою помилок і distributed spans.`},{id:`D`,text:`Зіставте критичні сервіси й дані з RPO/RTO, потім проєктуйте backup, реплікацію, автоматизацію відновлення, runbooks і тренування.`}]},{id:`T100-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Система бронювання може вимагати майже нульової втрати підтверджених платежів, але терпіти кілька годин втраченої аналітики.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Feature flag може окремо керувати новою поведінкою.`},{id:`B`,text:`Різним даним потрібні різні рівні захисту.`},{id:`C`,text:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`},{id:`D`,text:`Довгі WebSocket-з’єднання потребують іншої поведінки, ніж короткі HTTP.`}]},{id:`T100-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Резервні репліки зі спільною БД чи зоною хмари можуть мати спільну точку відмови.`},{id:`B`,text:`SLA не потрібно сліпо переносити в SLO.`},{id:`C`,text:`Автомасштабування не усуває послідовні вузькі місця й надмірну конкуренцію.`},{id:`D`,text:`Репліка не замінює перевірений backup: видалення й ransomware поширюються.`}]},{id:`T100-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`RPO — максимально допустимий проміжок втрати даних; RTO — цільовий час повернення сервісу після аварії.`}]}]},{id:`T100-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`RPO визначає швидкість відновлення, а RTO — припустиму втрату даних.`}]}]},{id:`T100-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Надто малі RPO/RTO дорогі й повинні відповідати бізнес-ризику та нормативним вимогам.`}]}]},{id:`T100-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`RPO — максимально допустимий проміжок втрати даних; RTO — цільовий час повернення сервісу після аварії.`},{id:`B`,text:`Неперевірених бекапів достатньо для гарантованого відновлення в межах RTO.`},{id:`C`,text:`Масштабованість та еластичність означають однакову поведінку потужностей.`},{id:`D`,text:`Зіставте критичні сервіси й дані з RPO/RTO, потім проєктуйте backup, реплікацію, автоматизацію відновлення, runbooks і тренування.`}]},{id:`T100-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Різним даним потрібні різні рівні захисту.`},{id:`B`,text:`Надто малі RPO/RTO дорогі й повинні відповідати бізнес-ризику та нормативним вимогам.`},{id:`C`,text:`RPO визначає швидкість відновлення, а RTO — припустиму втрату даних.`},{id:`D`,text:`Fallback із непомітно хибними цінами завжди кращий за помилку.`}]},{id:`T100-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Система бронювання може вимагати майже нульової втрати підтверджених платежів, але терпіти кілька годин втраченої аналітики.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента окремо змоделювати збої пошти, кешу й БД та визначити деградацію, тести відновлення й моніторинг.`},{id:`B`,text:`Попросіть агента змоделювати навантаження API бронювань, знайти вузькі місця, вибрати політику масштабування й захист БД від перевантаження.`},{id:`C`,text:`Попросіть агента визначити SLI підтвердження бронювань, вимірюваний SLO, пороги alert і політику error budget. Перевірте обґрунтованість усіх винятків.`},{id:`D`,text:`Попросіть агента скласти DR-план для бронювань, платежів та аналітики з окремими RPO/RTO, порядком відновлення, тестами backup і комунікацією.`}]},{id:`T100-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як перевірити відновлюваність backup до реальної аварії?`}]}]},{id:`T100-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Система бронювання може вимагати майже нульової втрати підтверджених платежів, але терпіти кілька годин втраченої аналітики.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T100-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Система бронювання може вимагати майже нульової втрати підтверджених платежів, але терпіти кілька годин втраченої аналітики.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T100-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Система бронювання може вимагати майже нульової втрати підтверджених платежів, але терпіти кілька годин втраченої аналітики.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T100-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Аварійне відновлення: RPO та RTO`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Система бронювання може вимагати майже нульової втрати підтверджених платежів, але терпіти кілька годин втраченої аналітики.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:100,questions:o};export{r as default,o as questions,i as slug,s as topicId};